const snapshot=async t=>Object.fromEntries(await Promise.all(stores.map(async name=>[name,await t.all(name)])));
export async function synchronizeGame(t,now){const d=await snapshot(t),date=dayKey(now),at=now.toISOString(),c=d.gameConfigurations.find(c=>c.id==='economy');let newly=[];
 const award=async(type,id,xp,coins,reason,evidence=[],earnedDate=date)=>{const key=type+':'+id;if(d.rewardLedger.some(r=>r.id===key||type==='session'&&r.sourceType==='legacy'&&r.sourceId==='session:'+id))return;const r={id:key,sourceType:type,sourceId:id,amount:xp,coins,date:earnedDate,at,reason,evidence};await t.put('rewardLedger',r);d.rewardLedger.push(r);if(xp||coins)newly.push(r)};
 const inventory=async(type,itemId,name)=>{const item={id:type+':'+itemId,type,itemId,name,at};if(!d.gameInventory.some(i=>i.id===item.id)){await t.put('gameInventory',item);d.gameInventory.push(item)}};
 const badge=async(def,evidence=[],earnedDate=date)=>{if(d.gameBadges.some(b=>b.id===def.id))return;const b={id:def.id,name:def.name,description:def.description,category:def.category,rarity:def.rarity,secret:!!def.secret,date:earnedDate,at,evidence,reward:{xp:def.xp,coins:def.coins},title:def.title||null};await t.put('gameBadges',b);d.gameBadges.push(b);await award('badge',b.id,def.xp,def.coins,b.name,evidence,earnedDate);if(def.title)await inventory('title',def.title,def.title);await t.put('gameCelebrations',{id:'badge:'+b.id,type:'badge',name:b.name,date,at,evidence:[{store:'gameBadges',id:b.id}],seen:false})};
 let plan=d.pillarPlans.find(p=>p.id===date);if(!plan){plan={id:date,date,items:pillars.map(p=>({id:p.id,planned:true,mode:'Normal'})),completed:{},requireWater:false,waterTarget:d.preferences.find(p=>p.id==='user')?.waterTarget||80,createdAt:at};await t.put('pillarPlans',plan);d.pillarPlans.push(plan)}
 const ordered=d.sessions.filter(safeSession).sort((a,b)=>a.date.localeCompare(b.date)||String(a.completedAt||a.startedAt).localeCompare(String(b.completedAt||b.startedAt))||a.id.localeCompare(b.id));const perDay={};for(const r of d.rewardLedger.filter(r=>r.sourceType==='session'||r.sourceType==='legacy'&&r.sourceId.startsWith('session:')))perDay[r.date]=(perDay[r.date]||0)+1;for(const s of ordered){const exists=d.rewardLedger.some(r=>r.id==='session:'+s.id||r.sourceType==='legacy'&&r.sourceId==='session:'+s.id);if(exists)continue;const count=perDay[s.date]||0;if(count<c.sessionDailyLimit){await award('session',s.id,50,10,'Workout completed · daily session cap',{store:'sessions',id:s.id},s.date);perDay[s.date]=count+1}}
 for(const s of ordered.filter(s=>s.date===date)){for(const id of sessionPillars(s,d.exercises)){if(!plan.items.some(i=>i.id===id&&i.planned)||plan.completed[id])continue;const completion={sessionId:s.id,at:s.completedAt||at,mode:s.mode||'Normal'};plan.completed[id]=completion;await award('pillar',date+':'+id,c.pillarXP,0,pillars.find(p=>p.id===id).name,[{store:'sessions',id:s.id}],date)}}await t.put('pillarPlans',plan);
 if(pillars.every(p=>plan.items.some(i=>i.id===p.id&&i.planned)&&plan.completed[p.id]))await award('quad',date,c.quadXP,10,'Quad Clear · planned exposure, not maximal effort',Object.values(plan.completed).map(v=>({store:'sessions',id:v.sessionId})));
 const routines=d.dailyStates.find(s=>s.id===date)?.routineTasks||[];if(routines.length&&routines.every((_,i)=>d.routineLogs.some(l=>l.date===date&&l.task===i&&l.done)))await award('routine',date,c.routineDailyXP,0,'Planned routine completed',[{store:'dailyStates',id:date}]);
 const checkin=d.checkins.find(c=>c.date===date);if(checkin)await award('checkin',date,c.checkinDailyXP,0,'Recovery / transformation check-in',[{store:'checkins',id:checkin.id}]);
 const safetyStop=d.sessions.find(s=>s.date===date&&s.safetyStop&&s.status==='partial');if(safetyStop)await award('safetyStop',date,5,0,'Stopped safely · recorded work preserved',[{store:'sessions',id:safetyStop.id}]);
 const improved=d.recordEvents.filter(r=>r.previous!==null&&r.date===date&&ordered.some(s=>s.id===r.sourceSession));if(improved.length)await award('pr',date,c.prDailyXP,3,'Meaningful PR · one daily reward',improved.map(r=>({store:'recordEvents',id:r.id})));
 const qualifying=d.attempts.filter(a=>a.date===date&&!a.pain&&(!a.sessionId||ordered.some(s=>s.id===a.sessionId))).filter(a=>{const skill=d.skillDefinitions.find(s=>s.id===a.skill),level=skill?.levelDefinitions.find(l=>l.id===a.levelId);return level?.requirements.some(r=>trialMeets(a,r))});if(qualifying.length)await award('trial',date,c.trialDailyXP,5,'Qualifying Dominance practice · daily cap',qualifying.map(a=>({store:'attempts',id:a.id})));
 for(const a of d.masteryAwards){const attempts=d.attempts.filter(p=>p.skill===a.skill&&p.levelId===a.levelId);if(!attempts.length||attempts.some(p=>p.sessionId&&d.sessions.find(s=>s.id===p.sessionId)?.revision>0))continue;await badge({id:'mastery:'+a.id,name:a.name,description:'Permanent mastery proved by activity-specific trials and repeatable practice.',category:'Dominance',rarity:'Rare',xp:75,coins:15,title:'Dominance Seeker'},[{store:'masteryAwards',id:a.id}],a.date)}
 for(const q of questCandidates(d,date))if(!d.gameQuests.some(old=>old.id===q.id)){const saved={...q,status:'planned',createdAt:at,evidence:[]};await t.put('gameQuests',saved);d.gameQuests.push(saved)}
 const week=weekStart(date);const walkingCapacity=Math.max(250,...ordered.flatMap(s=>s.logs.filter(l=>l.exerciseId==='walk').map(l=>l.distanceMeters||0)));const remainingDays=7-((now.getDay()+6)%7);const quadCount=d.rewardLedger.filter(r=>r.sourceType==='quad'&&r.date>=week&&r.date<=date).length;const mobilityCount=ordered.filter(s=>s.date>=week&&s.date<=date&&sessionPillars(s,d.exercises).includes('mobility')).length;const weekly=[{id:'weekly:mobility:'+week,name:'Mobility Week',target:Math.min(c.weekly.mobilitySessions,mobilityCount+remainingDays),kind:'mobility',minutes:8},{id:'weekly:quad:'+week,name:'Four Pillars Week',target:Math.min(c.weekly.quadDays,quadCount+remainingDays),kind:'quad',minutes:12},{id:'weekly:walking:'+week,name:'Walking Orbit',target:Math.min(c.weekly.walkingMeters,walkingCapacity*2),kind:'walking',minutes:10}];for(const w of weekly)if(!d.gameQuests.some(q=>q.id===w.id)){const q={...w,definitionVersion:2,type:'Weekly',date:week,deadline:dayKey(new Date(new Date(week+'T12:00:00').getTime()+6*86400000)),status:'planned',condition:'weekly',optional:true,priority:3,effort:'Light counts',reward:{xp:40,coins:10},createdAt:at,evidence:[]};await t.put('gameQuests',q);d.gameQuests.push(q)}else{const prior=d.gameQuests.find(q=>q.id===w.id);if(prior.status==='planned'&&prior.definitionVersion!==2){prior.target=Math.min(prior.target,w.target);prior.definitionVersion=2;await t.put('gameQuests',prior)}}
 for(const q of d.gameQuests.filter(q=>q.status!=='completed'&&q.status!=='archived'&&q.date<=date&&q.deadline>=date)){let evidence=[];if(q.condition==='pillar'&&plan.completed[q.pillarId])evidence=[{store:'sessions',id:plan.completed[q.pillarId].sessionId}];if(q.condition==='trial')evidence=qualifying.filter(a=>a.skill===q.skill&&a.levelId===q.levelId&&a.trial===q.trialId).map(a=>({store:'attempts',id:a.id}));if(q.condition==='routine'&&d.rewardLedger.some(r=>r.id==='routine:'+date))evidence=[{store:'dailyStates',id:date}];if(q.condition==='extra'&&dailyClear(d,date))evidence=ordered.filter(s=>s.date===date&&s.kind==='Extra'&&!s.pillarId).map(s=>({store:'sessions',id:s.id}));if(q.condition==='recovery')evidence=ordered.filter(s=>s.date===date&&['Recovery','Light / Rebuild'].includes(s.mode)).map(s=>({store:'sessions',id:s.id}));if(q.condition==='transformation-checkin')evidence=d.checkins.filter(c=>c.type==='weekly'&&c.date>=q.date&&c.date<=date).map(c=>({store:'checkins',id:c.id}));if(q.condition==='boss'){const boss=bossProgress(d,date).find(b=>b.id===q.bossId);if(boss?.complete)evidence=boss.evidence}if(q.condition==='weekly'){const sessions=ordered.filter(s=>s.date>=q.date&&s.date<=date&&sessionPillars(s,d.exercises).includes('mobility'));const quads=d.rewardLedger.filter(r=>r.sourceType==='quad'&&r.date>=q.date&&r.date<=date);const walks=ordered.filter(s=>s.date>=q.date&&s.date<=date).flatMap(s=>s.logs.filter(l=>l.exerciseId==='walk').map(l=>({session:s,log:l})));q.progress=q.kind==='quad'?quads.length:q.kind==='walking'?walks.reduce((n,w)=>n+(w.log.distanceMeters||0),0):sessions.length;if(q.progress>=q.target)evidence=q.kind==='quad'?quads.map(r=>({store:'rewardLedger',id:r.id})):q.kind==='walking'?walks.map(w=>({store:'sessions',id:w.session.id,setId:w.log.id})):sessions.map(s=>({store:'sessions',id:s.id}));await t.put('gameQuests',q)}if(!evidence.length)continue;q.status='completed';q.completedAt=at;q.evidence=evidence;await t.put('gameQuests',q);const paid=d.rewardLedger.filter(r=>r.date===date&&r.sourceType==='quest').length;if(q.type==='Weekly'||paid<c.questDailyLimit)await award('quest',q.id,q.reward.xp,q.reward.coins,q.name,evidence)}
 const trans=transformationSummary(d,date),active=streak(activityDates(d),date),first=ordered[0];const setEvidence=(predicate)=>{for(const s of ordered)for(const l of s.logs)if(l.form&&!l.pain&&predicate(l,s))return [{store:'sessions',id:s.id,setId:l.id}];return []};const conditions={
 'first-workout':first?[{store:'sessions',id:first.id}]:[],
 'first-pr':improved.map(r=>({store:'recordEvents',id:r.id})),
 mile:setEvidence(l=>['walk','run'].includes(l.exerciseId)&&l.distanceMeters>=1609.344),
 hang60:setEvidence(l=>['hang','supported-hang'].includes(l.exerciseId)&&l.durationSeconds>=60),
 active7:active.current>=7?[{store:'sessions',id:ordered.at(-1)?.id||null,stat:'active-day streak',value:active.current}]:[],
 'mobility-week':d.gameQuests.find(q=>q.id==='weekly:mobility:'+week&&q.status==='completed')?[{store:'gameQuests',id:'weekly:mobility:'+week}]:[],
 'smart-recovery':ordered.filter(s=>['Recovery','Light / Rebuild'].includes(s.mode)).map(s=>({store:'sessions',id:s.id})),
 week1:trans.elapsed>=7&&trans.checkins.length?trans.checkins.map(c=>({store:'checkins',id:c.id})):[],
 halfway:trans.halfway?trans.checkins.map(c=>({store:'checkins',id:c.id})):[],
 trend5:trans.weight.enough&&trans.weight.change>=c.transformation.weightChange?trans.weight.recentIds.map(id=>({store:'metrics',id})):[],
 waist1:trans.waist.enough&&trans.waist.change>=c.transformation.waistChange?trans.waist.recentIds.map(id=>({store:'metrics',id})):[],
 'strength-kept':trans.strengthKept?trans.strengthEvidence.map(id=>({stat:'controlled set',id})):[],
 'still-hungry':dailyClear(d,date)?ordered.filter(s=>s.date===date&&s.kind==='Extra'&&Object.values(plan.completed).every(p=>Date.parse(p.at)<=Date.parse(s.startedAt))&&routines.every((_,i)=>{const r=d.routineLogs.find(l=>l.date===date&&l.task===i&&l.done);return r?.at&&Date.parse(r.at)<=Date.parse(s.startedAt)})).map(s=>({store:'sessions',id:s.id})):[],
 comeback:comeback(d,date).returned&&dailyClear(d,date)?[{stat:'return date',value:date}]:[],
 'grip-gremlin':d.masteryAwards.filter(a=>a.skill==='grip'&&a.levelId==='grip-1').map(a=>({store:'masteryAwards',id:a.id})),
 'four-for-four':d.rewardLedger.some(r=>r.id==='quad:'+date)?[{store:'rewardLedger',id:'quad:'+date}]:[],
 'respect-recovery':ordered.filter(s=>s.recommendation?.lowReadiness&&['Recovery','Light / Rebuild'].includes(s.mode)).map(s=>({store:'sessions',id:s.id})),
 balance:balanceKept(d,date)?[{stat:'planned day preserved',value:date},...d.events.filter(e=>e.date===date&&e.category==='Personal Time'&&e.name.toLowerCase().includes('bae')).map(e=>({store:'events',id:e.id}))]:[]
 };for(const def of achievements)if(conditions[def.id]?.length)await badge(def,conditions[def.id]);
 for(const boss of bossProgress(d,date)){if(!boss.complete||boss.cleared||boss.evidence.some(e=>e.store==='masteryAwards'&&d.attempts.some(a=>d.masteryAwards.find(m=>m.id===e.id)?.skill===a.skill&&d.masteryAwards.find(m=>m.id===e.id)?.levelId===a.levelId&&a.sessionId&&d.sessions.find(s=>s.id===a.sessionId)?.revision>0)))continue;const proofAttempts=d.attempts.filter(a=>boss.evidence.some(e=>e.store==='masteryAwards'&&d.masteryAwards.find(m=>m.id===e.id)?.skill===a.skill&&d.masteryAwards.find(m=>m.id===e.id)?.levelId===a.levelId));const trace=[...boss.evidence,...proofAttempts.map(a=>({store:'attempts',id:a.id})),...proofAttempts.filter(a=>a.sessionId).map(a=>({store:'sessions',id:a.sessionId}))];const clear={id:boss.id,name:boss.name,date,at,title:boss.title,quote:boss.id==='transformation'&&trans.weight.change>0?"You didn't just lose weight. You built a more capable version of yourself.":boss.quote||null,rarity:boss.rarity,evidence:trace,stats:boss.id==='transformation'?{startingWeight:trans.config.startWeight,endingTrend:trans.weight.recent,weightTrend:trans.weight.change,waistChange:trans.waist.change,mastery:trans.mastery.length,prs:trans.records.length,activeDays:trans.activeDays,bodyControl:trans.mastery.filter(a=>['pull','push','grip'].includes(a.skill)).length,cardio:trans.mastery.filter(a=>a.skill==='run').length,carry:trans.mastery.filter(a=>a.skill==='carry').length,durationWeeks:trans.config.durationWeeks}: {path:boss.steps,proofMeasurements:proofAttempts.map(a=>({type:a.skill+' / '+a.trial,value:a.reps||a.seconds||a.distance,unit:a.reps?'reps':a.seconds?'seconds':'meters'})),relatedRecords:d.records.filter(r=>boss.evidence.some(e=>e.store==='masteryAwards'&&d.masteryAwards.find(a=>a.id===e.id)?.skill===d.exercises.find(x=>x.id===r.exerciseId)?.relatedDominancePath)).map(r=>({type:r.type,value:r.value,unit:r.unit}))},reward:{xp:boss.xp,coins:boss.coins}};await t.put('bossClears',clear);d.bossClears.push(clear);await award('boss',boss.id,boss.xp,boss.coins,'Boss cleared: '+boss.name,boss.evidence);await inventory('title',boss.title,boss.title);await badge({id:'boss:'+boss.id,name:boss.name,description:boss.description,category:'Boss',rarity:boss.rarity,xp:0,coins:0,title:boss.title},boss.evidence);await t.put('gameCelebrations',{id:'boss:'+boss.id,type:'boss',name:boss.name,date,at,evidence:[{store:'bossClears',id:boss.id}],seen:false})}
 const level=playerLevel(balances(d).xp,c);for(let n=2;n<=level.level;n++)await award('level',String(n),0,n%5===0?15:0,'Player Level '+n+' · engagement, not strength',[{stat:'player level',value:n}]);if(level.level>=5){await inventory('title','Galaxy Explorer','Galaxy Explorer');await inventory('cosmetic','orbit-frame','Orbit frame')}if(level.level>=10)await inventory('title','Unreasonably Determined','Unreasonably Determined');const previous=await t.get('gameProfile','player');if(level.level>(previous?.announcedLevel||1)){await t.put('gameCelebrations',{id:'level:'+level.level,type:'level',name:'Level '+level.level,date,at,evidence:[{stat:'player level',value:level.level}],seen:false});await t.put('gameProfile',{...previous,announcedLevel:level.level})}return newly;
}
export function gameActionRegistry(repo,clock){return {
 async createPersonalQuest({name,minutes,description}){if(typeof name!=='string'||!name.trim()||name.length>100||!Number.isInteger(minutes)||minutes<1||minutes>120||typeof description!=='string'||!description.trim()||description.length>1000)throw Error('Name a useful quest and its completion condition.');return repo.transact(['gameQuests'],async t=>{const date=dayKey(clock()),id='personal:'+date;if(await t.get('gameQuests',id))throw Error('A personal quest is already planned for today.');const q={id,name,description,minutes,date,deadline:date,type:'Personal',condition:'personal',optional:true,status:'planned',priority:2,effort:'Your choice',reward:{xp:10,coins:0},createdAt:clock().toISOString(),evidence:[]};await t.put('gameQuests',q);return q})},
 async completePersonalQuest({questId}){return repo.transact(['gameQuests','rewardLedger'],async t=>{const q=await t.get('gameQuests',questId),date=dayKey(clock());if(!q||q.condition!=='personal'||q.date!==date)throw Error('Select today’s personal quest.');if(q.status==='completed')return q;q.status='completed';q.completedAt=clock().toISOString();q.evidence=[{stat:'deliberate self-report',value:q.description}];await t.put('gameQuests',q);const id='quest:'+q.id;if(!await t.get('rewardLedger',id))await t.put('rewardLedger',{id,sourceType:'quest',sourceId:q.id,amount:10,coins:0,date,at:q.completedAt,reason:q.name,evidence:q.evidence});return q})},
 async syncGame(){return repo.transact(stores,t=>synchronizeGame(t,clock()))},
 async savePillarPlan({date=dayKey(clock()),items,requireWater=false}){if(!validDate(date)||date<dayKey(clock())||!Array.isArray(items)||items.length!==4||new Set(items.map(i=>i.id)).size!==4||items.some(i=>!pillars.some(p=>p.id===i.id)||typeof i.planned!=='boolean'||!['Normal','Light / Rebuild','Recovery'].includes(i.mode)))throw Error('Choose a valid plan for today.');return repo.transact(['pillarPlans'],async t=>{const prior=await t.get('pillarPlans',date);if(prior&&Object.keys(prior.completed).length)throw Error('Started pillar plans are preserved. Adjust tomorrow’s plan instead.');const plan={...prior,id:date,date,items,completed:{},requireWater,waterTarget:prior?.waterTarget||80,createdAt:prior?.createdAt||clock().toISOString()};await t.put('pillarPlans',plan);return plan})},
 async purchaseCosmetic({itemId}){const item=cosmetics.find(c=>c.id===itemId);if(!item)throw Error('Choose a catalog cosmetic.');return repo.transact(['rewardLedger','gameInventory'],async t=>{const id='cosmetic:'+item.id;if(await t.get('gameInventory',id))return await t.get('gameInventory',id);const ledger=await t.all('rewardLedger');if(ledger.reduce((n,r)=>n+r.coins,0)<item.cost)throw Error('Not enough coins.');const at=clock().toISOString();await t.put('rewardLedger',{id:'purchase:'+item.id,sourceType:'purchase',sourceId:item.id,amount:0,coins:-item.cost,date:dayKey(clock()),at,reason:'Cosmetic purchase: '+item.name,evidence:{catalog:item.id}});const owned={id,type:'cosmetic',itemId:item.id,name:item.name,at};await t.put('gameInventory',owned);return owned})},
 async equipGameItem({type,itemId}){return repo.transact(['gameInventory','gameProfile'],async t=>{const owned=await t.get('gameInventory',type+':'+itemId);if(!owned)throw Error('Earn or unlock this item first.');const profile=await t.get('gameProfile','player');if(type==='title')profile.title=itemId;else if(type==='cosmetic'){const item=cosmetics.find(c=>c.id===itemId);if(!item)throw Error('Cosmetic not found.');profile.equipped={...profile.equipped,[item.slot]:itemId}}else throw Error('Unsupported item type.');await t.put('gameProfile',profile);return profile})},
 async favoriteBadge({badgeId}){return repo.transact(['gameBadges','gameProfile'],async t=>{if(!await t.get('gameBadges',badgeId))throw Error('Earn this badge first.');const profile=await t.get('gameProfile','player');profile.favorites=profile.favorites.includes(badgeId)?profile.favorites.filter(id=>id!==badgeId):[...profile.favorites,badgeId].slice(-3);await t.put('gameProfile',profile);return profile})},
 async acknowledgeCelebration({id}){return repo.transact(['gameCelebrations'],async t=>{const item=await t.get('gameCelebrations',id);if(item)await t.put('gameCelebrations',{...item,seen:true})})},
 async stopSafely({sessionId}){return repo.transact(['sessions'],async t=>{const s=await t.get('sessions',sessionId);if(!s||!['active','paused'].includes(s.status))throw Error('Select an open session.');const next={...s,status:'partial',endedAt:clock().toISOString(),notes:'Stopped safely; recorded work is preserved.',safetyStop:true};await t.put('sessions',next);return next})}
}}
